// One Places call per area. Edit to your delivery zone.
const areas = ['restaurants in Bodija, Ibadan', 'hotels in Bodija, Ibadan', 'restaurants in Ring Road, Ibadan', 'restaurants in Jericho, Ibadan'];
return areas.map(textQuery => ({ json: { textQuery } }));

const known = new Set($('Pause switch and budget').first().json.known_places || []);
const seen = new Set();
const out = [];
for (const it of $('Places Text Search').all()) {
  for (const p of (it.json.places || [])) {
    if (!p.websiteUri || known.has(p.id) || seen.has(p.id)) continue;
    seen.add(p.id);
    out.push({ json: { place_id: p.id, company: p.displayName?.text || '', rating: p.rating || 0, reviews: p.userRatingCount || 0,
      website: p.websiteUri, address: p.formattedAddress || '' } });
  }
}
return out;

const html = String($json.html || '');
const text = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim().slice(0, 12000);
const p = $('New places with a website').item.json;
return { json: { ...p, text } };

