// The most important node: did the AI invent anything? Then score in code, not by feel.
const src = $('Page text').item.json;
const x = $json.output || $json;
const page = String(src.text || '').toLowerCase();
const q = String(x.fact_quote || '').toLowerCase().trim();
const verified = q.length > 12 && page.includes(q);
const emailOnPage = x.business_email && page.includes(String(x.business_email).toLowerCase()) ? String(x.business_email).toLowerCase() : null;
// ICP points (edit to match your ICP sheet)
const zone = ['bodija', 'ring road', 'jericho', 'agodi', 'iwo road', 'ui'];
let score = 0; const reasons = [];
if (zone.some(z => String(src.address).toLowerCase().includes(z))) { score += 25; reasons.push('in delivery zone'); }
if (src.rating >= 4.2) { score += 15; reasons.push('rating ' + src.rating); }
if (src.reviews >= 100) { score += 10; reasons.push(src.reviews + ' reviews'); }
if (x.offers_delivery) { score += 10; reasons.push('offers delivery'); }
if (x.office_lunch) { score += 15; reasons.push('office lunch'); }
if (/hotel|suites|inn/i.test(src.company)) { score += 10; reasons.push('hotel kitchen'); }
return { json: {
  place_id: src.place_id, company: src.company, website: src.website, address: src.address,
  domain: String(src.website).replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase(),
  email: emailOnPage, fact: verified ? x.fact : null, fact_source: verified ? src.website : null, fact_verified: verified,
  fit_score: score, reasons: reasons.join(', '),
  route: !emailOnPage ? 'manual' : score >= 60 ? 'draft' : 'skip'
} };

// Lint like the 5.2 lab; the code, not the AI, adds identity and opt-out.
const lead = $('Fit ≥ 60 with email').item.json;
let body = String($json.text || '').trim();
const problems = [];
const words = body.split(/\s+/).filter(Boolean).length;
if (words > 110) problems.push(words + ' words');
if ((body.match(/\?/g) || []).length !== 1) problems.push('needs exactly one question');
if (/(free money|guarantee|act now|limited time|100%|!!!|₦|\bdiscount)/i.test(body)) problems.push('spam word or price');
if (!lead.fact && /you (recently|just)|your new/i.test(body)) problems.push('claims a fact we did not verify');
body += '\n\nTolu Adebayo\nHarvest Lane · fresh produce for Ibadan kitchens · harvestlane.example\nNot interested? Reply STOP and we will never email you again.';
return { json: { ...lead, draft: body, lint_ok: problems.length === 0, lint: problems.join('; ') } };

